import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as a,o as r,c as i,ak as n}from"./chunks/framework.DC-k2h36.js";const o="/projects/esp32Sensor/en/latest/assets/1.yrQsggwA.webp",s="/projects/esp32Sensor/en/latest/assets/2.CH2DZUXc.webp",l="/projects/esp32Sensor/en/latest/assets/3.BsnGoXoS.webp",d="/projects/esp32Sensor/en/latest/assets/4.9yHnc8rR.webp",c="/projects/esp32Sensor/en/latest/assets/5.DNym88je.webp",x=JSON.parse('{"title":"11. Temperature and Humidity Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/11. Temperature and Humidity Sensor.md","filePath":"docs/11. Temperature and Humidity Sensor.md"}'),m={name:"docs/11. Temperature and Humidity Sensor.md"};function h(p,e,u,g,y,_){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_11-temperature-and-humidity-sensor" tabindex="-1">11. Temperature and Humidity Sensor <a class="header-anchor" href="#_11-temperature-and-humidity-sensor" aria-label="Permalink to &quot;11. Temperature and Humidity Sensor&quot;">​</a></h1><h2 id="_11-1-introduction" tabindex="-1">11.1 Introduction <a class="header-anchor" href="#_11-1-introduction" aria-label="Permalink to &quot;11.1 Introduction&quot;">​</a></h2><p>Featuring high precision and reliability, the temperature and humidity sensor detects ambient temperature and humidity, providing accurate environmental data feedback. This sensor enables the creation of a simple dehumidifier and pairs effectively with the fan module to build an automated fan control system.</p><img loading="lazy" height="1156" width="1156" src="'+o+'" class="common_img" style="width:300px;"><h2 id="_11-2-technical-specifications" tabindex="-1">11.2 Technical Specifications <a class="header-anchor" href="#_11-2-technical-specifications" aria-label="Permalink to &quot;11.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Temperature measurement range</td><td style="text-align:center;">-40°C to +85°C</td></tr><tr><td style="text-align:center;">Temperature accuracy</td><td style="text-align:center;">±0.3°C</td></tr><tr><td style="text-align:center;">Humidity measurement range</td><td style="text-align:center;">0 to 99.9% RH</td></tr><tr><td style="text-align:center;">Humidity accuracy</td><td style="text-align:center;">±2% RH at 25°C</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 16.7 mm</td></tr></tbody></table><h2 id="_11-3-hands-on-project" tabindex="-1">11.3 Hands-On Project <a class="header-anchor" href="#_11-3-hands-on-project" aria-label="Permalink to &quot;11.3 Hands-On Project&quot;">​</a></h2><h3 id="_11-3-1-project-overview" tabindex="-1">11.3.1 Project Overview <a class="header-anchor" href="#_11-3-1-project-overview" aria-label="Permalink to &quot;11.3.1 Project Overview&quot;">​</a></h3><p>This project uses the temperature and humidity sensor to collect ambient temperature and humidity values continuously, outputting temperature and humidity data via the serial port. Altering the environment around the sensor allows observation of changing serial data, illustrating the operating principle of temperature and humidity data acquisition.</p><h3 id="_11-3-2-hardware-wiring" tabindex="-1">11.3.2 Hardware Wiring <a class="header-anchor" href="#_11-3-2-hardware-wiring" aria-label="Permalink to &quot;11.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the temperature and humidity sensor to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="620" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_11-3-3-adding-extensions" tabindex="-1">11.3.3 Adding Extensions <a class="header-anchor" href="#_11-3-3-adding-extensions" aria-label="Permalink to &quot;11.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Temperature and humidity sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_11-3-4-complete-program-and-analysis" tabindex="-1">11.3.4 Complete Program and Analysis <a class="header-anchor" href="#_11-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;11.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, temperature and humidity readings from the temperature and humidity sensor on port P1 are continuously acquired.</p></li><li><p>The collected temperature and humidity values are printed via the serial port.</p></li><li><p>A 0.5 s delay is added to regulate the data refresh rate and stabilize serial readings.</p></li></ol><img loading="lazy" height="291" width="721" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/11 Temperature and Humidity Sensor.sb3</a>.</strong></p></div><h3 id="_11-3-5-program-upload" tabindex="-1">11.3.5 Program Upload <a class="header-anchor" href="#_11-3-5-program-upload" aria-label="Permalink to &quot;11.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_11-3-6-program-outcome" tabindex="-1">11.3.6 Program Outcome <a class="header-anchor" href="#_11-3-6-program-outcome" aria-label="Permalink to &quot;11.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, observe the serial monitor in the lower-right corner of the programming software. The serial port continuously outputs labeled <code>Temperature</code> and <code>Humidity</code> values. Placing a hand near the sensor or breathing gently onto it causes the temperature reading to rise slightly and the humidity reading to increase noticeably, providing a clear demonstration of ambient environmental changes.</p><img loading="lazy" height="960" width="1350" src="'+c+'" class="common_img" style="width:500px;">',26)])])}const P=a(m,[["render",h]]);export{x as __pageData,P as default};
